                    // Akce bez parametru
                    that.actions.actDetail.updatePermission(jePrazdnySeznam ? { value: false } : { value: true }); // aktualizace přístupnosti
                    that.actions.actDetailDoZalozky.updatePermission(jePrazdnySeznam ? { value: false } : { value: true }); // aktualizace přístupnosti
                    that.actions.actOznacitJakoPrectene.updatePermission(jePrazdnySeznam ? { value: false } : { value: true }); // aktualizace přístupnosti
                    that.actions.actOznacitJakoNeprectene.updatePermission(jePrazdnySeznam ? { value: false } : { value: true }); // aktualizace přístupnosti
                    that.actions.actZmenaStavuZauctovani.updatePermission(jePrazdnySeznam ? { value: false } : { value: true }); // aktualizace přístupnosti
                    that.actions.actUvolneniProstredku.updatePermission(jePrazdnySeznam ? { value: false } : { value: true }); // aktualizace přístupnosti
                    that.actions.actZmenaDatumuSplatnosti.updatePermission(jePrazdnySeznam ? { value: false } : { value: true }); // aktualizace přístupnosti
                    that.actions.actPridatPorovnavac.updatePermission(jePrazdnySeznam ? { value: false } : { value: true }); // aktualizace přístupnosti
                    that.actions.actKontrolaMetadat.updatePermission(jePrazdnySeznam ? { value: false } : { value: true }); // aktualizace přístupnosti
                    that.actions.actTisk.updatePermission(jePrazdnySeznam ? { value: false } : { value: true }); // aktualizace přístupnosti
                    // Akce s parametrem
                    that.actions.actPodani.updatePermission(permissions?.["LzePodat"]); // aktualizace přístupnosti
                    that.actions.actPodaniDleVzoru.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzePodat"]); // aktualizace přístupnosti
                    that.actions.actPredani.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzePredat"]); // aktualizace přístupnosti
                    that.actions.actPrideleni.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzePridelit"]); // aktualizace přístupnosti
                    that.actions.actPrevzeti.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzePrevzit"]); // aktualizace přístupnosti
                    that.actions.actPreevidence.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzePreevidovat"]); // aktualizace přístupnosti
                    that.actions.actStorno.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzeStornovat"]); // aktualizace přístupnosti
                    that.actions.actOdstorno.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzeZrusitStorno"]); // aktualizace přístupnosti
                    that.actions.actUzavreni.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzeUzavrit"]); // aktualizace přístupnosti
                    that.actions.actZruseniUzavreni.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzeZrusitUzavreni"]); // aktualizace přístupnosti
                    that.actions.actUctovani.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzeUctovat"]); // aktualizace přístupnosti
                    that.actions.actUhrada.updatePermission(jePrazdnySeznam ? { value: false } : permissions?.["LzeUhradit"]); // aktualizace přístupnosti
